public interface IHandler<in T>
{
    void Handle(T message);
}

public class Bus
{
    readonly List<object> _handlers = new();

    public void Subscribe(object handler)
    {
        ArgumentNullException.ThrowIfNull(handler);
        if (!_handlers.Contains(handler)) _handlers.Add(handler);
    }

    public void Unsubscribe(object handler) => _handlers.Remove(handler);

    public int Publish<T>(T message)
    {
        int handled = 0;
        var errors = new List<Exception>();
        foreach (var h in _handlers.ToList())
        {
            if (h is not IHandler<T> handler) continue;
            handled++;
            try { handler.Handle(message); }
            catch (Exception e) { errors.Add(e); }
        }
        if (errors.Count > 0) throw new AggregateException(errors);
        return handled;
    }
}

unitTests:
Test("a base-type handler receives derived messages", () =>
{
    var bus = new Bus();
    var log = new Log();
    var clicks = new ClickCounter();
    bus.Subscribe(log);
    bus.Subscribe(clicks);
    CheckEq(bus.Publish(new Click("button", 1, 2)), 2);
    CheckEq(bus.Publish(new Key("keyboard", 'a')), 1);
    CheckEq(string.Join(";", log.Lines), "Click from button;Key from keyboard");
    CheckEq(clicks.Count, 1);
});

Test("unsubscribe", () =>
{
    var bus = new Bus();
    var log = new Log();
    bus.Subscribe(log);
    bus.Unsubscribe(log);
    CheckEq(bus.Publish(new Event("x")), 0);
    CheckEq(log.Lines.Count, 0);
});

Test("one broken handler does not stop the rest", () =>
{
    var bus = new Bus();
    var log = new Log();
    bus.Subscribe(new Broken());
    bus.Subscribe(log);
    CheckThrows<AggregateException>(() => bus.Publish(new Event("x")));
    CheckEq(log.Lines.Count, 1);
});

Test("subscribing twice counts once", () =>
{
    var bus = new Bus();
    var clicks = new ClickCounter();
    bus.Subscribe(clicks);
    bus.Subscribe(clicks);
    bus.Publish(new Click("b", 0, 0));
    CheckEq(clicks.Count, 1);
});

