public record Event(string Source);
public record Click(string Source, int X, int Y) : Event(Source);
public record Key(string Source, char Char) : Event(Source);

public class Log : IHandler<Event>
{
    public List<string> Lines { get; } = new();
    public void Handle(Event e) => Lines.Add($"{e.GetType().Name} from {e.Source}");
}

public class ClickCounter : IHandler<Click>
{
    public int Count { get; private set; }
    public void Handle(Click c) => Count++;
}

public class Broken : IHandler<Event>
{
    public void Handle(Event e) => throw new InvalidOperationException("broken handler");
}
